                out.write("TRANSLATED");
                return consumedAmount;
            }
            return 0;
        }
    }











    @Test
    public void testTranslate_ComplexLogic_BranchCoverage() throws IOException {
        // This test targets the specific branch: if (pos < len - 2) vs else { pos++ }
        // and the loop increments.

        // We use a translator that consumes 2 "units" (simulating a surrogate pair handling)
        // to trigger the 'else' branch inside the 'consumed > 0' block.
        CharSequenceTranslator translator = new TestTranslator(2, 'A');
        StringWriter out = new StringWriter();

        // Input: "A" (1 codepoint, but 2 chars in UTF-16 if it were a surrogate, 
        // but here we use a single char to hit the 'else' branch where pos is not < len-2)
        translator.translate("A", out);
        assertEquals("TRANSLATED", out.toString());
    }




}

